-- Employee Atlas seed data (multi-tenant, generated).
-- Development-only password for all app users: AtlasDemo2026!
set search_path = public;

-- ── Tenants ──

-- ── App users (profiles are created by the on_auth_user_created trigger) ──
do $$
declare
  u record;
begin
  for u in
    select * from (values
      ('a0000000-0000-4000-8000-000000000001'::uuid, 'superadmin@demo.com',      'super_admin',  null::uuid,                                    'Atlas Platform Admin'),
      ('a0000000-0000-4000-8000-000000000011'::uuid, 'tav.admin@demo.com',       'tenant_admin', 'e0000000-0000-4000-8000-000000000001'::uuid,  'Selin Aydoğan'),
      ('a0000000-0000-4000-8000-000000000012'::uuid, 'tav.hr@demo.com',          'hr',           'e0000000-0000-4000-8000-000000000001'::uuid,  'Aylin Koçer'),
      ('a0000000-0000-4000-8000-000000000013'::uuid, 'tav.manager@demo.com',     'manager',      'e0000000-0000-4000-8000-000000000001'::uuid,  'Cem Yalçın'),
      ('a0000000-0000-4000-8000-000000000021'::uuid, 'turkcell.admin@demo.com',  'tenant_admin', 'e0000000-0000-4000-8000-000000000002'::uuid,  'Emre Şahin'),
      ('a0000000-0000-4000-8000-000000000022'::uuid, 'turkcell.hr@demo.com',     'hr',           'e0000000-0000-4000-8000-000000000002'::uuid,  'Zeynep Demirtaş'),
      ('a0000000-0000-4000-8000-000000000023'::uuid, 'turkcell.manager@demo.com','manager',      'e0000000-0000-4000-8000-000000000002'::uuid,  'Kaan Özkan')
    ) as t(id, email, role, tenant_id, full_name)
  loop
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change, email_change_token_new)
    values ('00000000-0000-0000-0000-000000000000', u.id, 'authenticated', 'authenticated', u.email,
      extensions.crypt('AtlasDemo2026!', extensions.gen_salt('bf')), now(),
      jsonb_strip_nulls(jsonb_build_object('provider', 'email', 'providers', jsonb_build_array('email'), 'role', u.role, 'tenant_id', u.tenant_id)),
      jsonb_build_object('full_name', u.full_name), now(), now(), '', '', '', '');
    values (gen_random_uuid(), u.id, u.id,
      jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true), 'email', now(), now(), now());
  end loop;
end $$;

