select t.id, f.key
from tenants t
cross join (values
  ('email'), ('phone'), ('internal_ext'), ('manager_name'), ('start_date'),
  ('education'), ('certifications'), ('languages'), ('past_projects'), ('hobbies')
) as f(key);
